package paasio

import (
	"io"
	"sync"
)

// readCounter wraps an io.Reader and reports the total number of bytes
// successfully read along with the total number of calls to Read().
type readCounter struct {
	r io.Reader

	mu   sync.Mutex
	n    int64
	nops int
}

// NewReadCounter returns a ReadCounter that wraps reader and reports
// statistics about the bytes read from it.
func NewReadCounter(reader io.Reader) ReadCounter {
	return &readCounter{r: reader}
}

func (rc *readCounter) Read(p []byte) (int, error) {
	n, err := rc.r.Read(p)
	rc.mu.Lock()
	rc.nops++
	if err == nil {
		rc.n += int64(n)
	}
	rc.mu.Unlock()
	return n, err
}

// ReadCount returns the total number of bytes successfully read along
// with the total number of calls to Read().
func (rc *readCounter) ReadCount() (int64, int) {
	rc.mu.Lock()
	defer rc.mu.Unlock()
	return rc.n, rc.nops
}

// writeCounter wraps an io.Writer and reports the total number of bytes
// successfully written along with the total number of calls to Write().
type writeCounter struct {
	w io.Writer

	mu   sync.Mutex
	n    int64
	nops int
}

// NewWriteCounter returns a WriteCounter that wraps writer and reports
// statistics about the bytes written to it.
func NewWriteCounter(writer io.Writer) WriteCounter {
	return &writeCounter{w: writer}
}

func (wc *writeCounter) Write(p []byte) (int, error) {
	n, err := wc.w.Write(p)
	wc.mu.Lock()
	wc.nops++
	if err == nil {
		wc.n += int64(n)
	}
	wc.mu.Unlock()
	return n, err
}

// WriteCount returns the total number of bytes successfully written along
// with the total number of calls to Write().
func (wc *writeCounter) WriteCount() (int64, int) {
	wc.mu.Lock()
	defer wc.mu.Unlock()
	return wc.n, wc.nops
}

// readWriteCounter wraps an io.ReadWriter and reports statistics for both
// the bytes read and the bytes written.
type readWriteCounter struct {
	*readCounter
	*writeCounter
}

// NewReadWriteCounter returns a ReadWriteCounter that wraps readwriter and
// reports statistics about the bytes read from and written to it.
func NewReadWriteCounter(readwriter io.ReadWriter) ReadWriteCounter {
	return &readWriteCounter{
		readCounter:  NewReadCounter(readwriter).(*readCounter),
		writeCounter: NewWriteCounter(readwriter).(*writeCounter),
	}
}
